package com.bank.core;

import java.util.Objects;

// WRONG: overrides equals but NOT hashCode → inherited identity hashCode.
public class BrokenAccount {
    private final String accountId;
    public BrokenAccount(String accountId) { this.accountId = accountId; }

    @Override
    public boolean equals(Object o) {
        if (this == o) return true;
        if (!(o instanceof BrokenAccount)) return false;
        return Objects.equals(accountId, ((BrokenAccount) o).accountId);
    }
    // hashCode NOT overridden → equal objects get DIFFERENT buckets.
}
