package com.bank.core;

import java.util.Objects;

// CORRECT: both derived from the SAME field.
public class CorrectAccount {
    private final String accountId;
    public CorrectAccount(String accountId) { this.accountId = accountId; }

    @Override
    public boolean equals(Object o) {
        if (this == o) return true;
        if (!(o instanceof CorrectAccount)) return false;
        return Objects.equals(accountId, ((CorrectAccount) o).accountId);
    }
    @Override
    public int hashCode() {
        return Objects.hash(accountId); // consistent with equals
    }
}
