package com.bank.core;

import java.util.HashMap;
import java.util.Map;
import java.util.logging.*;

public class EqualsHashCodeDemo {
    private static final Logger log = Logger.getLogger("BankLog");
    static {
        Handler h = new ConsoleHandler();
        h.setFormatter(new SimpleFormatter());
        log.setUseParentHandlers(false);
        log.addHandler(h);
        log.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        // BROKEN: equal keys, different buckets → lookup fails.
        Map<BrokenAccount, String> broken = new HashMap<>();
        broken.put(new BrokenAccount("SAV2001"), "PREMIUM");
        String b = broken.get(new BrokenAccount("SAV2001"));
        log.warning(() -> "Broken lookup (expected null) → " + b);

        // CORRECT: equal keys, same bucket, equals confirms → lookup works.
        Map<CorrectAccount, String> correct = new HashMap<>();
        correct.put(new CorrectAccount("SAV2001"), "PREMIUM");
        String c = correct.get(new CorrectAccount("SAV2001"));
        log.info(() -> "Correct lookup → " + c);
    }
}
